using UnityEngine;

public class BurnDoTEffect : DoTEffect
{
	private static GameObject prefab;

	public static string burnStatusStr = "BurnStatus";

	public BurnEffect burnEffect;

	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/Effects/BurnEffect.prefab");
			}
			return prefab;
		}
	}

	public BurnDoTEffect(string newCat, int newLvl, Entity newEnt, Entity atkEnt)
		: base(newCat, burnStatusStr, newLvl, newEnt, atkEnt)
	{
		dotElement = ElementType.Fire;
	}

	public override void Init()
	{
		base.Init();
		burnEffect = Object.Instantiate(Prefab, parentEntity.transform.position, Quaternion.identity).GetComponent<BurnEffect>();
		burnEffect.entity = parentEntity;
		SoundManager.PlayAudioWithDistance("FlameLight", parentEntity.transform.position);
	}

	public override void CleanUp()
	{
		if (burnEffect != null)
		{
			burnEffect.Disable();
		}
	}
}
using UnityEngine;

public class PoisonDotEffect : DoTEffect
{
	public static string poisonStatusStr = "PoisonStatus";

	public PoisonEffect poisonEffect;

	private PoisonType poisonType;

	public PoisonDotEffect(string newCat, int newLvl, Entity newEnt, Entity atkEnt)
		: base(newCat, poisonStatusStr, newLvl, newEnt, atkEnt)
	{
		sfxName = "PoisonEffect";
		randomFacingDir = true;
		if (newCat.Contains("Enemy"))
		{
			poisonType = PoisonType.Purple;
		}
		dotElement = ElementType.Earth;
	}

	public override void Init()
	{
		base.Init();
		poisonEffect = Globals.ChaosInst<PoisonEffect>(PoisonEffect.Prefab, null, parentEntity.transform.position);
		poisonEffect.entity = parentEntity;
		poisonEffect.poisonType = poisonType;
	}

	public override void InitDotVars()
	{
		base.InitDotVars();
		string audioID = "ImpactPoison";
		Vector2? soundOrigin = parentEntity.transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
	}

	public override void CleanUp()
	{
		if (poisonEffect != null)
		{
			poisonEffect.Disable();
		}
	}
}

