			currentFO.Freeze(parent.transform);
			if (parent.health.lastAttack != null)
			{
				parent.ApplyKnockback(parent.health.lastAttack);
				freezeDuration = parent.health.lastAttack.freezeDuration;
			}
			freezeStopwatchID = ChaosStopwatch.Begin(freezeDuration * durationMultiplier);
